def evaluate(expr: str) -> float:
    pos = 0
    n = len(expr)

    def skip_spaces() -> None:
        nonlocal pos
        while pos < n and expr[pos].isspace():
            pos += 1

    def parse_expression() -> float:
        nonlocal pos
        value = parse_term()

        while True:
            skip_spaces()
            if pos < n and expr[pos] in "+-":
                op = expr[pos]
                pos += 1
                rhs = parse_term()
                value = value + rhs if op == "+" else value - rhs
            else:
                return value

    def parse_term() -> float:
        nonlocal pos
        value = parse_unary()

        while True:
            skip_spaces()
            if pos < n and expr[pos] in "*/":
                op = expr[pos]
                pos += 1
                rhs = parse_unary()
                if op == "*":
                    value *= rhs
                else:
                    if rhs == 0.0:
                        raise ZeroDivisionError("division by zero")
                    value /= rhs
            else:
                return value

    def parse_unary() -> float:
        nonlocal pos
        skip_spaces()
        if pos < n and expr[pos] == "-":
            pos += 1
            return -parse_unary()
        return parse_primary()

    def parse_primary() -> float:
        nonlocal pos
        skip_spaces()

        if pos >= n:
            raise ValueError("unexpected end of expression")

        if expr[pos] == "(":
            pos += 1
            value = parse_expression()
            skip_spaces()
            if pos >= n or expr[pos] != ")":
                raise ValueError("unbalanced parentheses")
            pos += 1
            return value

        start = pos

        if expr[pos].isdigit():
            while pos < n and expr[pos].isdigit():
                pos += 1
            if pos < n and expr[pos] == ".":
                pos += 1
                while pos < n and expr[pos].isdigit():
                    pos += 1
        elif expr[pos] == ".":
            pos += 1
            digit_start = pos
            while pos < n and expr[pos].isdigit():
                pos += 1
            if pos == digit_start:
                raise ValueError("malformed number")
        else:
            raise ValueError("unexpected character")

        try:
            return float(expr[start:pos])
        except ValueError as exc:
            raise ValueError("malformed number") from exc

    skip_spaces()
    if pos >= n:
        raise ValueError("empty expression")

    result = parse_expression()

    skip_spaces()
    if pos != n:
        raise ValueError("malformed expression")

    return float(result)
